21	    --code-str: #c5e478;
22	    --code-num: #ffd479;
23	    --code-com: #6b7585;
24	    --code-ty: #7cc4ff;
25	    --code-fn: #ffe18a;
26	  }
27	  * { box-sizing: border-box; }
28	  html, body { margin: 0; padding: 0; background: var(--bg); color: var(--ink); }
29	  body {
30	    font: 16px/1.65 -apple-system, "SF Pro Text", "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
