42	    text-transform: uppercase; margin-right: 6px;
43	  }
44	  code, pre, .mono { font-family: "JetBrains Mono", "SF Mono", Menlo, Consolas, monospace; }
45	  code { background: var(--code-bg); padding: 1px 6px; border-radius: 4px; font-size: 14px; }
46	  pre {
47	    background: var(--code-bg); padding: 16px 18px; border-radius: 8px;
