70	    background: var(--panel); border: 1px solid var(--rule);
71	    border-radius: 10px; padding: 14px 16px; margin: 14px 0;
72	  }
73	  .question p.q { margin: 0 0 10px; font-weight: 600; }
74	  ul.options { list-style: none; padding: 0; margin: 8px 0 0; }
